class BoxFilter {
public:
    std::array<float, 2> _area_range;

    std::vector<size_t> _select_boxes_by_area(const NDArray& boxes_xyxy) {
        if (_area_range[0] == 0.0f && _area_range[1] == 0.0f) {
            throw std::invalid_argument("Area range must be specified to filter boxes by area");
        }

        std::vector<size_t> selected_indices;

        for (size_t i = 0; i < boxes_xyxy.size(); ++i) {
            const auto& box = boxes_xyxy[i];
            float width = box[2] - box[0];
            float height = box[3] - box[1];
            float area = width * height;

            if (area >= _area_range[0] && area <= _area_range[1]) {
                selected_indices.push_back(i);
            }
        }

        return selected_indices;
    }
};
